import {amount,today,uid,validDate} from './model.js';
const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const rub=n=>(n/100).toLocaleString('ru-RU',{maximumFractionDigits:2})+' ₽';
const money=s=>{const v=String(s).replace(/[\s\u00a0₽]/g,'').replace(',','.');return !v||Number(v)===0?0:amount(v);};
export function createFinanceTables({root,getData,save,getYear,getMonth,getKind,salaryFields,salaryValues,categories}){
 let dirty=false,busy=false;const isSalary=c=>salaryFields.some(x=>x[1]===c);
 const input=(value,attrs)=>`<input ${attrs} value="${esc(value)}" data-original="${esc(value)}">`;
 function toolbar(type){return `<div class="grid-toolbar"><span class="grid-status" role="status">Все изменения сохранены</span><div><button data-grid="cancel">Отменить изменения</button><button data-grid="save" data-type="${type}" class="primary">Сохранить изменения</button></div></div><p class="footnote">Tab — следующее поле · Enter — подтвердить ячейку · Esc — вернуть её значение. Можно вставить диапазон из Excel; перед сохранением проверьте значения.</p><p class="error grid-error" role="alert"></p>`;}
 function salaryView(){const year=getYear(),month=getMonth(),periods=Array.from({length:12},(_,i)=>`${year}-${String(i+1).padStart(2,'0')}`).filter(p=>month==='all'||p.slice(5)===month);return `<h3>Зарплата · таблица за ${year} год</h3>${toolbar('salary')}<div class="finance-grid-wrap"><table class="finance-grid salary-grid"><thead><tr><th>Месяц</th>${salaryFields.map(([label])=>`<th>${label}, ₽</th>`).join('')}<th>Итого</th><th>ТПР</th></tr></thead><tbody>${periods.map(p=>{const values=salaryValues(p),total=values.reduce((a,b)=>a+b,0),prior=salaryValues(`${year-1}-${p.slice(5)}`).reduce((a,b)=>a+b,0);return `<tr data-period="${p}" data-prior="${prior}"><th>${new Date(p+'-01T12:00:00').toLocaleDateString('ru-RU',{month:'long'})}</th>${values.map((v,i)=>`<td>${input(v?v/100:'',`data-cell="${i}" aria-label="${p} ${salaryFields[i][0]}" inputmode="decimal"`)}</td>`).join('')}<td data-total>${rub(total)}</td><td data-growth>${prior?((total-prior)/prior*100).toFixed(1)+'%':'—'}</td></tr>`;}).join('')}</tbody><tfoot><tr><th>Итого</th>${salaryFields.map((_,i)=>`<td data-column="${i}">${rub(periods.reduce((n,p)=>n+salaryValues(p)[i],0))}</td>`).join('')}<td data-grand>${rub(periods.reduce((n,p)=>n+salaryValues(p).reduce((a,b)=>a+b,0),0))}</td><td></td></tr></tfoot></table></div>`;}
 const bankFields=['month','bank','category','amount','date','note'];
 function bankRow(x,isNew=false){const readonly=isSalary(x.category);return `<tr data-id="${esc(x.id)}" ${isNew?'data-new="true"':''} ${readonly?'data-readonly="true"':''}>${bankFields.map((k,i)=>`<td>${readonly?esc(k==='amount'?rub(x.amount):x[k]||'—'):k==='category'?`<select data-field="category" data-cell="${i}" data-original="${esc(x.category)}" aria-label="Вид дохода ${esc(x.id)}">${categories.filter(c=>!isSalary(c)).map(c=>`<option ${c===x.category?'selected':''}>${esc(c)}</option>`).join('')}</select>`:input(k==='amount'?x.amount/100:x[k]||'',`data-field="${k}" data-cell="${i}" aria-label="${k} ${esc(x.id)}" ${k==='month'?'type="month"':k==='date'?'type="date"':k==='amount'?'inputmode="decimal"':''}`)}</td>`).join('')}</tr>`;}
 function incomesView(){const y=getYear(),m=getMonth(),k=getKind(),rows=getData().incomes.filter(x=>x.month.startsWith(y+'-')&&(m==='all'||x.month===`${y}-${m}`)&&(k==='all'||x.category===k)).sort((a,b)=>a.month.localeCompare(b.month)||a.bank.localeCompare(b.bank,'ru'));return `<div class="row between"><h3>Поступления · таблица</h3><button data-grid="add" class="primary">＋ Строка</button></div>${toolbar('bank')}<p class="footnote">Зарплатные строки доступны для просмотра; суммы зарплаты меняйте на вкладке «Зарплата». Прибыль от продаж рассчитывается в своих разделах.</p><div class="finance-grid-wrap"><table class="finance-grid bank-grid"><thead><tr>${['Месяц учёта','Банк / источник','Вид дохода','Сумма, ₽','Дата получения','Комментарий'].map(x=>`<th>${x}</th>`).join('')}</tr></thead><tbody>${rows.map(x=>bankRow(x)).join('')}</tbody><tfoot><tr><th colspan="3">Итого поступления</th><td data-bank-total>${rub(rows.reduce((n,x)=>n+x.amount,0))}</td><td colspan="2"></td></tr></tfoot></table></div>`;}
 function setDirty(){dirty=true;const s=root.querySelector('.grid-status');if(s)s.textContent='Есть несохранённые изменения';}
 function update(){const rows=root.querySelectorAll('.salary-grid tbody tr');let grand=0,columns=[0,0,0,0,0];for(const row of rows){let total=0;try{row.querySelectorAll('input').forEach((e,i)=>{const n=money(e.value);total+=n;columns[i]+=n;});row.querySelector('[data-total]').textContent=rub(total);const prior=Number(row.dataset.prior);row.querySelector('[data-growth]').textContent=prior?((total-prior)/prior*100).toFixed(1)+'%':'—';grand+=total;}catch{row.querySelector('[data-total]').textContent='Проверьте сумму';}}if(rows.length){root.querySelector('[data-grand]').textContent=rub(grand);columns.forEach((n,i)=>root.querySelector(`[data-column="${i}"]`).textContent=rub(n));}const out=root.querySelector('[data-bank-total]');if(out){let total=0;try{root.querySelectorAll('.bank-grid tbody tr').forEach(row=>{total+=row.dataset.readonly?getData().incomes.find(x=>x.id===row.dataset.id).amount:money(row.querySelector('[data-field="amount"]').value);});out.textContent=rub(total);}catch{out.textContent='Проверьте сумму';}}}
 function applySalary(){const changes=[];root.querySelectorAll('.salary-grid tbody tr').forEach(row=>{const values=[...row.querySelectorAll('input')].map(e=>money(e.value));changes.push([row.dataset.period,values]);});for(const [period,values]of changes){const current=salaryValues(period);values.forEach((value,i)=>{const delta=value-current[i];if(!delta)return;const data=getData(),category=salaryFields[i][1],existing=data.incomes.find(x=>x.salaryAdjustment&&x.category===category&&x.month===period);if(existing){existing.amount+=delta;existing.date=today();}else data.incomes.push({id:uid(),category,amount:delta,date:today(),month:period,bank:'Сводный ввод зарплаты',note:'Из таблицы зарплаты',salaryAdjustment:true});});}}
 function applyBank(){const records=[];root.querySelectorAll('.bank-grid tbody tr:not([data-readonly])').forEach(row=>{const record={id:row.dataset.id};bankFields.forEach(k=>record[k]=row.querySelector(`[data-field="${k}"]`).value.trim());record.amount=money(record.amount);if(!/^20\d\d-(0[1-9]|1[0-2])$/.test(record.month)||!record.bank||record.bank.length>100||record.note.length>500||record.date&&!validDate(record.date)||!categories.includes(record.category)||isSalary(record.category))throw Error('Проверьте месяц, банк, категорию и дату поступления.');records.push(record);});for(const record of records){const old=getData().incomes.find(x=>x.id===record.id);if(old)Object.assign(old,record);else getData().incomes.push(record);}}
 root.addEventListener('input',e=>{if(!e.target.closest('.salary-grid,.bank-grid'))return;setDirty();update();});root.addEventListener('change',e=>{if(e.target.closest('.salary-grid,.bank-grid')){setDirty();update();}});
 root.addEventListener('keydown',e=>{if(!e.target.matches('.salary-grid input,.bank-grid input,.bank-grid select'))return;if(e.key==='Escape'){e.target.value=e.target.dataset.original;setDirty();update();}if(e.key==='Enter'){e.preventDefault();e.target.blur();}});
 root.addEventListener('paste',e=>{const cell=e.target.closest('.salary-grid [data-cell],.bank-grid [data-cell]');if(!cell)return;const text=e.clipboardData.getData('text/plain');if(!/[\t\r\n]/.test(text))return;e.preventDefault();const rows=[...cell.closest('tbody').querySelectorAll('tr')],startRow=rows.indexOf(cell.closest('tr')),startCol=Number(cell.dataset.cell),matrix=text.trimEnd().split(/\r?\n/).map(s=>s.split('\t'));if(startRow+matrix.length>rows.length){root.querySelector('.grid-error').textContent='Недостаточно строк. Добавьте строки или уменьшите диапазон.';return;}const staged=[];for(let i=0;i<matrix.length;i++)for(let j=0;j<matrix[i].length;j++){const target=rows[startRow+i].querySelector(`[data-cell="${startCol+j}"]`);if(!target){root.querySelector('.grid-error').textContent='Вставляйте только диапазон полей ввода, без итогов и заголовков.';return;}let value=matrix[i][j].trim();if(target.matches('select')&&![...target.options].some(o=>o.value===value)){root.querySelector('.grid-error').textContent='Категория в Excel не совпадает с категориями приложения.';return;}if(target.type==='date'&&/^\d{2}\.\d{2}\.\d{4}$/.test(value))value=value.split('.').reverse().join('-');staged.push([target,value]);}staged.forEach(([target,value])=>target.value=value);setDirty();update();root.querySelector('.grid-error').textContent='';});
 root.addEventListener('click',async e=>{const b=e.target.closest('[data-grid]');if(!b||busy)return;const action=b.dataset.grid;if(action==='add'){const tbody=root.querySelector('.bank-grid tbody'),m=getMonth(),y=getYear();tbody.insertAdjacentHTML('beforeend',bankRow({id:uid(),month:`${y}-${m==='all'?today().slice(5,7):m}`,bank:'',category:'Кэшбэк',amount:0,date:today(),note:''},true));setDirty();tbody.lastElementChild.querySelector('[data-field="bank"]').focus();return;}if(action==='cancel'){root.querySelectorAll('.finance-grid [data-original]').forEach(x=>x.value=x.dataset.original);root.querySelectorAll('[data-new]').forEach(x=>x.remove());dirty=false;update();root.querySelector('.grid-status').textContent='Изменения отменены';root.querySelector('.grid-error').textContent='';return;}if(action==='save'){busy=true;b.disabled=true;const error=root.querySelector('.grid-error');try{if(b.dataset.type==='salary')applySalary();else applyBank();await save();dirty=false;}catch(err){error.textContent=err.message;root.querySelector('.grid-status').textContent='Не сохранено. Проверьте данные или обновите страницу.';}finally{busy=false;b.disabled=false;}}});
 return {salaryView,incomesView,hasDirty:()=>dirty};
}
